/* cppi::b1710560c3ba52366ba849725c21a4035ef9657f1c88082b929e09ef2c38c3e0 */
select business_date as date_, security_id, 'JPR' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-24' and business_date <= date '2025-06-24' and weight_ndo>0 and id_cppib_index = 'JPR_GR_USD_0_0' and security_id is not null

